#requires -Version 7.0
[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$ToolRoot = Split-Path -Parent $PSCommandPath
$Inner = Join-Path $ToolRoot 'Invoke-GPIHub-V101-Target-Parity.ps1'
$Generated = Join-Path $ToolRoot 'Invoke-GPIHub-V101-Target-Parity-REV3.generated.ps1'

if (-not (Test-Path -LiteralPath $Inner -PathType Leaf)) {
    throw "Base V101 script missing: $Inner"
}

$text = Get-Content -LiteralPath $Inner -Raw

$targetPattern = '(?s)    \$TargetPrecheck = @''\r?\n.*?\r?\n''@\r?\n    \$pre = Invoke-SshScript'
$targetMatches = [regex]::Matches($text,$targetPattern)
if ($targetMatches.Count -ne 1) {
    throw "Expected exactly one V101 TargetPrecheck block; found $($targetMatches.Count)."
}
$targetB64 = ''
$targetReplacement = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($targetB64)) + "`r`n    `$pre = Invoke-SshScript"
$text = [regex]::Replace($text,$targetPattern,[System.Text.RegularExpressions.MatchEvaluator]{ param($m) $targetReplacement },1)

$sourcePattern = '(?s)    \$SourceHealth = @''\r?\n.*?\r?\n''@\r?\n    \$src = Invoke-SshScript'
$sourceMatches = [regex]::Matches($text,$sourcePattern)
if ($sourceMatches.Count -ne 1) {
    throw "Expected exactly one V101 SourceHealth block; found $($sourceMatches.Count)."
}
$sourceB64 = ''
$sourceReplacement = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($sourceB64)) + "`r`n    `$src = Invoke-SshScript"
$text = [regex]::Replace($text,$sourcePattern,[System.Text.RegularExpressions.MatchEvaluator]{ param($m) $sourceReplacement },1)

Set-Content -LiteralPath $Generated -Value $text -Encoding utf8 -NoNewline

$tokens = $null
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($Generated,[ref]$tokens,[ref]$errors) | Out-Null
if ($errors.Count -gt 0) {
    $detail = ($errors | ForEach-Object { $_.Message }) -join '; '
    throw "Generated V101 REV3 parser validation failed: $detail"
}

Write-Host 'V101_REV3_INTERNAL_NETWORK_PRECHECK_PATCH=PASS' -ForegroundColor Green
Write-Host 'V101_REV3_SOURCE_INTERNAL_HEALTH_PATCH=PASS' -ForegroundColor Green
Write-Host 'V101_REV3_GENERATED_PARSER=PASS' -ForegroundColor Green
Write-Host "Generated script: $Generated"

& pwsh.exe -NoProfile -ExecutionPolicy Bypass -File $Generated
exit $LASTEXITCODE
